#include "dfre/mission_terrain_content.hpp"
#include <fstream>
#include <iostream>
#include <sstream>
#include <filesystem>
#include <map>
namespace {using U=std::uint32_t;
struct Fixture{U seed,count,pointer,mode,fault,reads=0;std::uint64_t trace=1469598103934665603ull;std::array<U,256>table{};std::map<U,std::uint8_t>changed;
void event(U v){for(U i=0;i<4;++i){trace^=std::uint8_t(v>>(8*i));trace*=1099511628211ull;}}
U byte(U a){if(a>=0x4f8720&&a<0x4f8b20)return (table[(a-0x4f8720)/4]>>((a&3)*8))&255u;const auto i=changed.find(a);return i==changed.end()?((a*13u+seed*17u)^(a>>5))&255u:i->second;}
U read(U a,U width){event(a);event(width);if(++reads==fault)throw std::runtime_error("Read failure");if(width==1){if(mode&1)for(auto&w:table)w^=seed+reads;return byte(a);}if(width!=4||a<0x4f8720||a>=0x4f8b20)throw std::runtime_error("Unmapped CRC table read");const auto value=table[(a-0x4f8720)/4];if(mode&2){const U next=pointer+reads/2;changed[next]=std::uint8_t(byte(next)^0xa5);}return value;}
};
void write(const std::filesystem::path&p,const dfre::AssetBytes&v){std::ofstream f(p,std::ios::binary);f.write(reinterpret_cast<const char*>(v.data()),std::streamsize(v.size()));if(!f)throw std::runtime_error("Cannot export terrain content fixture");}
void assets(const std::filesystem::path&game,const std::string&mission,const std::filesystem::path&out){dfre::AssetStore a(game);const auto runtime=dfre::load_terrain_runtime(a,mission);const auto values=dfre::mission_terrain_content(a,runtime);std::filesystem::create_directories(out);std::int32_t configured_water=0;for(const auto&f:runtime.config.fields)if(f.name=="water_height"&&f.values.size()==1)configured_water=std::stoi(f.values[0])*16384;std::cout<<"{\"configured_water\":"<<configured_water<<",\"mission\":\""<<mission<<"\",\"water\":"<<runtime.water_height<<",\"sky\":"<<bool(runtime.sky)<<",\"values\":[";for(U i=0;i<9;++i)std::cout<<(i?",":"")<<values[i];std::cout<<"],\"images\":[";bool first=true;for(const auto&f:runtime.config.fields){if(f.values.size()!=1)continue;if(f.name!="color_map"&&f.name!="elev_map"&&f.name!="detail_map"&&f.name!="detail_color"&&f.name!="detail_elev"&&f.name!="detail_shade"&&f.name!="sky_map"&&f.name!="sky_palette"&&f.name!="water_map"&&f.name!="water_palette")continue;const auto n=f.values[0]+".PCX";if(!first)std::cout<<',';first=false;bool present=false;for(const auto&archive:a.archives())for(const auto&e:archive.entries())if(!e.deleted){auto x=e.name,y=n;for(auto&c:x)if(c>='A'&&c<='Z')c+=32;for(auto&c:y)if(c>='A'&&c<='Z')c+=32;if(x==y)present=true;}std::cout<<"{\"key\":\""<<f.name<<"\",\"name\":\""<<n<<"\",\"present\":"<<present;if(present){const auto raw=a.read(n);const auto image=dfre::decode_pcx(raw.bytes);write(out/(f.name+".pcx"),raw.bytes);write(out/(f.name+".pixels"),image.pixels);write(out/(f.name+".palette"),image.palette);std::cout<<",\"archive\":\""<<raw.source.archive<<"\",\"offset\":"<<raw.source.offset<<",\"raw_size\":"<<raw.source.size<<",\"width\":"<<image.width<<",\"height\":"<<image.height;}std::cout<<'}';}std::cout<<"]}\n";}
}
int main(int argc,char**argv){try{if(argc==5&&std::string(argv[1])=="assets"){assets(argv[2],argv[3],argv[4]);return 0;}if(argc!=1)throw std::runtime_error("Use: mission_terrain_content_probe [assets GAME MISSION OUTPUT]");std::string line;while(std::getline(std::cin,line)){if(line.empty())continue;Fixture f{};std::istringstream in(line);if(!(in>>f.seed>>f.count>>f.pointer>>f.mode>>f.fault))return 2;for(U i=0;i<256;++i){U v=i<<24;for(U bit=0;bit<8;++bit)v=(v<<1)^((v&0x80000000u)?0x04c11db7u:0u);f.table[i]=v;}dfre::MissionClientAddedBindings b;b.read=[&](U a,U w){return f.read(a,w);};bool failed=false;U value=0;try{value=dfre::mission_terrain_crc(b,f.pointer,f.count);}catch(const std::exception&){failed=true;}std::cout<<failed<<' '<<f.reads<<' '<<f.trace<<' '<<value<<'\n';}return 0;}catch(const std::exception&e){std::cerr<<e.what()<<'\n';return 1;}}
